\begin{lemma}\label{lem:martingale_brownian_sq_sub_time}
  \uses{def:brownianNaturalFiltration}
  \lean{ProbabilityTheory.martingale_brownian_sq_sub_time}
The process \(B_t^2-t\) is a martingale with respect to the natural Brownian filtration.
\end{lemma}

\begin{proof}

It is adapted because \(B_t\) is \(\mathcal F^B_t\)-measurable and \(t\) is
deterministic.  It is integrable because \(B_t\) is Gaussian with finite second
moment.

Fix \(s\le t\) and write \(\Delta_{s,t}=B_t-B_s\).  Then
\[
  B_t^2-t
  = B_s^2-s + 2B_s\Delta_{s,t}
    +\bigl(\Delta_{s,t}^2-(t-s)\bigr).
\]
The increment \(\Delta_{s,t}\) is independent of \(\mathcal F^B_s\), centered,
and has law \(N(0,t-s)\).  Therefore
\[
  \mathbb E[\Delta_{s,t}\mid\mathcal F^B_s]=0,
  \qquad
  \mathbb E[\Delta_{s,t}^2\mid\mathcal F^B_s]=t-s.
\]
Since \(B_s\) is \(\mathcal F^B_s\)-measurable, the mixed term has conditional
expectation
\[
  \mathbb E[B_s\Delta_{s,t}\mid\mathcal F^B_s]
  = B_s\,\mathbb E[\Delta_{s,t}\mid\mathcal F^B_s]=0.
\]
Taking conditional expectations in the displayed expansion gives
\[
  \mathbb E[B_t^2-t\mid\mathcal F^B_s]=B_s^2-s,
\]
which is the martingale property.
\end{proof}

\begin{lemma}\label{lem:quadraticVariation_brownian}
  \uses{def:brownianQuadraticVariation, lem:martingale_brownian_sq_sub_time, lem:predictablePart_eq_of_normalized_decomposition}
  \lean{ProbabilityTheory.quadraticVariation_brownian}
Let \(B\) be the canonical Brownian motion. Then its quadratic variation is
given by \(\langle B \rangle_t = t\).
\end{lemma}

\begin{proof}
The candidate Doob--Meyer decomposition of \(B_t^2\) is
\[
  B_t^2 = (B_t^2-t) + t.
\]
By Lemma~\ref{lem:martingale_brownian_sq_sub_time}, the first summand is a
local martingale.  The second summand is deterministic, càdlàg, predictable,
locally integrable, nondecreasing, and starts from zero.  A normalized
Doob--Meyer uniqueness theorem therefore identifies the predictable part of
\(B_t^2\) with \(t\).

In the current Lean route this last step must use a predictable-part
identification theorem for normalized Doob--Meyer decompositions.  Without the
normalization \(A_0=0\), the predictable part is not unique: one can shift a
constant between the martingale and finite-variation parts.  Thus the equality
\(\langle B\rangle_t=t\) should not be formalized from the present
choice-based \texttt{predictablePart} API until that uniqueness/normalization input is
available.
\end{proof}


\begin{definition}[Continuous semi-martingale]\label{def:continuousSemiMartingale}
  \uses{def:IsLocalMartingale}
A continuous semi-martingale is a process that can be decomposed into a local martingale and a finite variation process.
More formally, a process $X : \mathbb{R}_+ \to \Omega \to E$ is a continuous semi-martingale if there exists a continuous local martingale $M$ and a continuous adapted process $A$ with locally finite variation and $A_0 = 0$ such that
\begin{align*}
  X_t = M_t + A_t
\end{align*}
for all $t \ge 0$.
The decomposition is a.s. unique.
\end{definition}
